        /**
         * ConfigOverrides
         * @description Optional public configuration overrides for the balancing algorithm.
         */
        "balancer.ConfigOverrides": {
            /**
             * Average Mmr Balance Weight
             * @description Penalty weight for differences between team average MMR values.
             * @default null
             */
            average_mmr_balance_weight: number | null;
            /**
             * Convergence Epsilon
             * @description Minimum relative improvement required to continue once convergence patience is reached.
             * @default null
             */
            convergence_epsilon: number | null;
            /**
             * Convergence Patience
             * @description Generations without meaningful Pareto improvement before early stopping can trigger.
             * @default null
             */
            convergence_patience: number | null;
            /**
             * Crossover Rate
             * @description Probability of crossover when producing offspring in the Rust MOO search.
             * @default null
             */
            crossover_rate: number | null;
            /**
             * Effective Total Std Weight
             * @description Penalty multiplier for weighted effective team-total standard deviation.
             * @default null
             */
            effective_total_std_weight: number | null;
            /**
             * Generation Count
             * @description Maximum optimization iterations. Higher values can improve quality and increase runtime.
             * @default null
             */
            generation_count: number | null;
            /**
             * Greedy Seed Count
             * @description How many initial individuals are built with greedy seeding before random fill.
             * @default null
             */
            greedy_seed_count: number | null;
            /**
             * Internal Role Spread Weight
             * @description Penalty weight for uneven average strength between roles inside the same team.
             * @default null
             */
            internal_role_spread_weight: number | null;
            /**
             * Intra Team Std Weight
             * @description Weight for the standard deviation of ratings inside each team. Higher values push the optimizer to spread top players across teams.
             * @default null
             */
            intra_team_std_weight: number | null;
            /**
             * Island Count
             * @description Number of independent Rust MOO islands explored in parallel before merging the archive.
             * @default null
             */
            island_count: number | null;
            /**
             * Low Rank Collision Weight
             * @description Penalty weight per pair of low-rank players in the same team, normalized per team count. Discourages stacking two low-rank players together.
             * @default null
             */
            low_rank_collision_weight: number | null;
            /**
             * Low Rank Threshold
             * @description Players whose best role rating is at or below this value (canonical scale, see rating_scale_ceiling) count as low-rank; teams with two or more of them get penalized. 0 disables the mechanic.
             * @default null
             */
            low_rank_threshold: number | null;
            /**
             * Max Result Variants
             * @description Maximum number of solution variants returned by the selected solver.
             * @default null
             */
            max_result_variants: number | null;
            /**
             * Max Role Discomfort Weight
             * @description Penalty weight for the single worst role discomfort assignment in a solution.
             * @default null
             */
            max_role_discomfort_weight: number | null;
            /**
             * Max Team Gap Weight
             * @description Penalty weight for the rating gap between the strongest and weakest teams.
             * @default null
             */
            max_team_gap_weight: number | null;
            /**
             * Mix Comfort Tilt
             * @description Mix trade-off between rank balance and role comfort. 0 weighs only how evenly the two teams' ranks split, 1 only how many players got a preferred role; 0.5 reproduces the engine's own defaults.
             * @default null
             */
            mix_comfort_tilt: number | null;
            /**
             * Mutation Rate
             * @description Probability that a solution is changed while producing the next generation.
             * @default null
             */
            mutation_rate: number | null;
            /**
             * Mutation Rate Max
             * @description Upper bound for the adaptive mutation rate during Rust MOO search.
             * @default null
             */
            mutation_rate_max: number | null;
            /**
             * Mutation Rate Min
             * @description Lower bound for the adaptive mutation rate during Rust MOO search.
             * @default null
             */
            mutation_rate_min: number | null;
            /**
             * Mutation Strength
             * @description Number of swap/change operations attempted during a mutation.
             * @default null
             */
            mutation_strength: number | null;
            /**
             * @description Weights of open slots without a role constraint.
             * @default null
             */
            open_slot_settings: components["schemas"]["balancer.RoleSettingsOverride"] | null;
            /**
             * Polish Max Passes
             * @description Maximum local-improvement passes applied to each archive solution after the main search.
             * @default null
             */
            polish_max_passes: number | null;
            /**
             * Population Size
             * @description Number of candidate balances kept per generation. Higher values improve search coverage and cost more time.
             * @default null
             */
            population_size: number | null;
            /**
             * Rank Comfort Tilt
             * @description Shifts how result variants are ranked: 0.5 weighs team balance (StdDev) and comfort (off-role) equally; toward 1 prioritises comfort/off-role, toward 0 prioritises balance. Ordering and primary selection only — does not change the optimizer search.
             * @default null
             */
            rank_comfort_tilt: number | null;
            /**
             * Role Discomfort Weight
             * @description Penalty weight for assigning players away from their preferred roles.
             * @default null
             */
            role_discomfort_weight: number | null;
            /**
             * Role Line Balance Weight
             * @description Penalty weight for uneven rating strength between the same role across teams.
             * @default null
             */
            role_line_balance_weight: number | null;
            /**
             * Role Settings
             * @description Per-role weights keyed by roster slot code: how much a role counts towards a team's effective total, and how hard uneven lines of it are penalized.
             * @default null
             */
            role_settings: {
                [key: string]: components["schemas"]["balancer.RoleSettingsOverride"];
            } | null;
            /**
             * Stagnation Kick Patience
             * @description Generations without archive improvement before stronger mutation and crossover are applied.
             * @default null
             */
            stagnation_kick_patience: number | null;
            /**
             * Sub Role Collision Weight
             * @description Penalty weight per pair of players in the same team sharing the same role subclass, normalized per team count. Use 0 to disable.
             * @default null
             */
            sub_role_collision_weight: number | null;
            /**
             * Team Max Pain Weight
             * @description Penalty weight for the per-team maximum role discomfort averaged over all teams. Makes 'one suffering player in every team' visible, unlike the single global maximum.
             * @default null
             */
            team_max_pain_weight: number | null;
            /**
             * Team Total Balance Weight
             * @description Penalty weight for standard deviation of total team rating sums.
             * @default null
             */
            team_total_balance_weight: number | null;
            /**
             * Time Limit Ms
             * @description Hard wall-clock budget for the optimizer in milliseconds. When exceeded, evolution and polishing stop early and the best result found so far is returned. Trades same-seed reproducibility for latency.
             * @default null
             */
            time_limit_ms: number | null;
            /**
             * Use Captains
             * @description Marks top-rated players as captains and uses them as team anchors when supported by the solver.
             * @default null
             */
            use_captains: boolean | null;
        };
